'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

function* partitions(text) {
  yield text.split('');
  for (let first = 0; first <= text.length; first++) {
    for (let second = first; second <= text.length; second++) {
      yield [text.slice(0, first), '', text.slice(first, second), '', text.slice(second)];
    }
  }
}

test('records remain exact across all two-boundary partitions', () => {
  const cases = [
    ['', []], ['\uFEFF', []], ['\n', [['']]], ['\r\n', [['']]],
    ['\n\n', [[''], ['']]], ['\r\r\n\n', [[''], [''], ['']]],
    ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
    [',', [['', '']]], ['left,,right,', [['left', '', 'right', '']]],
    ['""', [['']]], ['""""', [['"']]],
    ['a"b,c"d', [['a"b', 'c"d']]], [' "literal"', [[' "literal"']]],
    ['"a,b","say ""hi"""\r\n', [['a,b', 'say "hi"']]],
    ['"first\r\nsecond\rthird\nfourth",tail\n', [['first\r\nsecond\rthird\nfourth', 'tail']]],
    ['\uFEFFa,\uFEFFb\n\uFEFFc', [['a', '\uFEFFb'], ['\uFEFFc']]],
    ['\uFEFF\uFEFF', [['\uFEFF']]], ['😀,"😀"', [['😀', '😀']]],
    ['a\r\n\r\nb', [['a'], [''], ['b']]],
  ];
  for (const [text, expected] of cases) {
    assert.deepEqual(parse(text), expected);
